  UNSPECIFIED
  BULK
  OVERVIEW
  TABLE

type TemplateResponse* = object
  ## Template fields
  adAccountId*: Option[string] ## ID of the Ad Account that owns the template
  adAccountIds*: Option[seq[string]] ## IDs of the Ad Accounts that have access to this template
  clickWindowDays*: Option[float] ## The length of the sliding window over which click conversions will be attributed
  columns*: Option[Columns] ## A list of columns to be included in the report
  conversionReportTimeType*: Option[ConversionReportTimeType] ## Conversion report time type
  creationSource*: Option[CreationSource] ## The surface used to create this template
  customColumnIds*: Option[seq[string]] ## A list of custom column IDs
  dateRange*: Option[TemplateResponse_date_range]
  engagementWindowDays*: Option[float] ## The length of the sliding window over which engagement conversions will be attributed
  filtersJson*: Option[string] ## A JSON representation of any filters to be applied before returning report data. Each filter object should contain all of the following fields:<br> \"field\": The column name<br> \"operator\": The operator. Allowed operators: [\"=\", \"!=\", \"in\", \"not_in\", \"~\", \">\", \"<\", \"contains_substring\"]<br> \"value\": A single value or a list of values
  granularity*: Option[Granularity]
  id*: Option[string] ## Template ID
  ingestionSources*: Option[IngestionSources] ## The filter on the conversion ingestion source method for conversion metrics
  isDeleted*: Option[bool] ## A boolean that indicates if the template has been deleted
  isOwnedByUser*: Option[bool] ## A boolean value that indicates if the user owns the template
  isScheduled*: Option[bool] ## A boolean value that indicates if this template has been used to create a scheduled report
  name*: Option[string] ## Template Name
  reportEndRelativeDaysInPast*: Option[float] ## The number of days prior to the day the report will be delivered at which the report will end
  reportFormat*: Option[DataOutputFormat]
  reportLevel*: Option[MetricsReportingLevel]
  reportStartRelativeDaysInPast*: Option[float] ## The number of days prior to the day the report will be delivered at which the report will start
  `type`*: Option[`Type`] ## Reporting template type
  updatedTime*: Option[float] ## Time of last update in seconds since Unix epoch
  userId*: Option[string] ## ID of the user who created the template
  viewWindowDays*: Option[float] ## The length of the sliding window over which view conversions will be attributed

